def award_existing_completed_orders(apps, schema_editor):
    Order = apps.get_model("orders", "Order")
    PointsTransaction = apps.get_model("accounts", "PointsTransaction")
    database = schema_editor.connection.alias
    for order in Order.objects.using(database).filter(
        status="delivered",
        customer_id__isnull=False,
    ).iterator():
        points = int(order.subtotal // Decimal("10000"))
        if points:
            PointsTransaction.objects.using(database).get_or_create(
                order_id=order.pk,
                kind="earned",
                defaults={
                    "user_id": order.customer_id,
                    "points": points,
                    "description": f"Tích điểm đơn {order.order_number}",
                },
            )


